export function getDocHubData(locale: string): HubTranslation {
  const rawLoc = (locale || 'en').trim();
  const cleanLoc = rawLoc.toLowerCase();
  const fn = hubTranslations[rawLoc] ||
             hubTranslations[cleanLoc] ||
             hubTranslations[rawLoc.replace('_', '-')] ||
             (cleanLoc.startsWith('zh') ? (cleanLoc.includes('tw') || cleanLoc.includes('hant') ? hubTranslations['zh-TW'] : hubTranslations['zh']) : undefined) ||
             hubTranslations['en'];
  return fn(rawLoc);
}
